[{"order":1,"type":"heading","text":"Angular Route Guards: Controlling Navigation"},{"order":2,"type":"paragraph","text":"Route guards in Angular are interfaces that determine if a route can be activated, deactivated, or if data should be resolved before a route is activated. They provide a way to control navigation based on certain conditions, such as user authentication, authorization, or data availability. This tutorial covers `CanActivate`, `CanDeactivate`, and `Resolve` guards."},{"order":3,"type":"subheading","text":"CanActivate: Protecting Routes"},{"order":4,"type":"paragraph","text":"The `CanActivate` guard determines if a user can access a specific route. It's commonly used for authentication and authorization. If the guard returns `true`, the route is activated; otherwise, navigation is blocked."},{"order":5,"type":"code","text":"// auth.guard.ts
import { Injectable } from '@angular/core';
import { CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot, Router } from '@angular/router';
import { Observable } from 'rxjs';
import { AuthService } from './auth.service';

@Injectable({
  providedIn: 'root'
})
export class AuthGuard implements CanActivate {

  constructor(private authService: AuthService, private router: Router) {}

  canActivate(
    next: ActivatedRouteSnapshot,
    state: RouterStateSnapshot): Observable<boolean> | Promise<boolean> | boolean {
    if (this.authService.isAuthenticated()) {
      return true;
    } else {
      this.router.navigate(['/login'], { queryParams: { returnUrl: state.url }});
      return false;
    }
  }

}"},{"order":6,"type":"paragraph","text":"Explanation: The `AuthGuard` implements the `CanActivate` interface. The `canActivate` method checks if the user is authenticated using `AuthService`. If authenticated, it returns `true`, allowing access. Otherwise, it redirects to the login page with a `returnUrl` query parameter and returns `false`."},{"order":7,"type":"code","text":"// app-routing.module.ts
import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { HomeComponent } from './home/home.component';
import { LoginComponent } from './login/login.component';
import { AuthGuard } from './auth.guard';

const routes: Routes = [
  { path: 'home', component: HomeComponent, canActivate: [AuthGuard] },
  { path: 'login', component: LoginComponent },
  { path: '', redirectTo: '/home', pathMatch: 'full' }
];

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule]
})
export class AppRoutingModule { }
"},{"order":8,"type":"paragraph","text":"Explanation: In the `AppRoutingModule`, the `canActivate` property is added to the 'home' route, specifying `AuthGuard`. This ensures that only authenticated users can access the home component."},{"order":9,"type":"subheading","text":"CanDeactivate: Preventing Route Exits"},{"order":10,"type":"paragraph","text":"The `CanDeactivate` guard determines if a user can navigate away from a route. It's useful for preventing users from leaving a page with unsaved changes. The guard can prompt the user for confirmation before allowing navigation."},{"order":11,"type":"code","text":"// unsaved-changes.guard.ts
import { Injectable } from '@angular/core';
import { CanDeactivate, ActivatedRouteSnapshot, RouterStateSnapshot } from '@angular/router';
import { Observable } from 'rxjs';

export interface CanComponentDeactivate {
  canDeactivate: () => Observable<boolean> | Promise<boolean> | boolean;
}

@Injectable({
  providedIn: 'root'
})
export class UnsavedChangesGuard implements CanDeactivate<CanComponentDeactivate> {
  canDeactivate(
    component: CanComponentDeactivate,
    currentRoute: ActivatedRouteSnapshot,
    currentState: RouterStateSnapshot,
    nextState?: RouterStateSnapshot): Observable<boolean> | Promise<boolean> | boolean {

    return component.canDeactivate ? component.canDeactivate() : true;
  }

}"},{"order":12,"type":"paragraph","text":"Explanation: The `UnsavedChangesGuard` implements the `CanDeactivate` interface. It checks if the component has a `canDeactivate` method. If it does, it calls the method to determine if navigation is allowed. The `CanComponentDeactivate` interface defines the contract for components that need to implement the `canDeactivate` method."},{"order":13,"type":"code","text":"// edit.component.ts
import { Component } from '@angular/core';
import { Observable } from 'rxjs';
import { CanComponentDeactivate } from './unsaved-changes.guard';

@Component({
  selector: 'app-edit',
  template: `<p>Edit Component</p><button (click)="hasChanges = true">Make Changes</button><a routerLink="/home">Go Home</a>`,
  styles: []
})
export class EditComponent implements CanComponentDeactivate {
  hasChanges = false;

  canDeactivate(): Observable<boolean> | Promise<boolean> | boolean {
    if (this.hasChanges) {
      return confirm('Are you sure you want to discard changes?');
    }
    return true;
  }
}
"},{"order":14,"type":"paragraph","text":"Explanation: The `EditComponent` implements the `CanComponentDeactivate` interface. The `canDeactivate` method prompts the user for confirmation if there are unsaved changes. If the user confirms, it returns `true`, allowing navigation; otherwise, it returns `false`, preventing navigation."},{"order":15,"type":"code","text":"// app-routing.module.ts
import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { HomeComponent } from './home/home.component';
import { LoginComponent } from './login/login.component';
import { EditComponent } from './edit/edit.component';
import { UnsavedChangesGuard } from './unsaved-changes.guard';

const routes: Routes = [
  { path: 'home', component: HomeComponent },
  { path: 'login', component: LoginComponent },
  { path: 'edit', component: EditComponent, canDeactivate: [UnsavedChangesGuard] },
  { path: '', redirectTo: '/home', pathMatch: 'full' }
];

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule]
})
export class AppRoutingModule { }
"},{"order":16,"type":"paragraph","text":"Explanation: In the `AppRoutingModule`, the `canDeactivate` property is added to the 'edit' route, specifying `UnsavedChangesGuard`. This ensures that the user is prompted for confirmation before leaving the edit component if there are unsaved changes."},{"order":17,"type":"subheading","text":"Resolve: Fetching Data Before Route Activation"},{"order":18,"type":"paragraph","text":"The `Resolve` guard fetches data before a route is activated. This ensures that the component has the necessary data before it's rendered, preventing errors or empty states. It's useful for fetching data from an API or database."},{"order":19,"type":"code","text":"// data.resolver.ts
import { Injectable } from '@angular/core';
import { Resolve, ActivatedRouteSnapshot, RouterStateSnapshot } from '@angular/router';
import { Observable } from 'rxjs';
import { DataService } from './data.service';

@Injectable({
  providedIn: 'root'
})
export class DataResolver implements Resolve<any> {

  constructor(private dataService: DataService) {}

  resolve(
    route: ActivatedRouteSnapshot,
    state: RouterStateSnapshot
  ): Observable<any> | Promise<any> | any {
    const id = route.paramMap.get('id');
    return this.dataService.getData(id);
  }

}"},{"order":20,"type":"paragraph","text":"Explanation: The `DataResolver` implements the `Resolve` interface. The `resolve` method fetches data using `DataService` based on the 'id' parameter in the route. The data is then made available to the component."},{"order":21,"type":"code","text":"// details.component.ts
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';

@Component({
  selector: 'app-details',
  template: `<p>Details Component</p><p>Data: {{ data | json }}</p>`,
  styles: []
})
export class DetailsComponent implements OnInit {
  data: any;

  constructor(private route: ActivatedRoute) { }

  ngOnInit() {
    this.data = this.route.snapshot.data['data'];
  }

}"},{"order":22,"type":"paragraph","text":"Explanation: The `DetailsComponent` retrieves the resolved data from the `ActivatedRoute` snapshot. The data is accessed using the key 'data', which is specified in the route configuration."},{"order":23,"type":"code","text":"// app-routing.module.ts
import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { HomeComponent } from './home/home.component';
import { LoginComponent } from './login/login.component';
import { DetailsComponent } from './details/details.component';
import { DataResolver } from './data.resolver';

const routes: Routes = [
  { path: 'home', component: HomeComponent },
  { path: 'login', component: LoginComponent },
  { path: 'details/:id', component: DetailsComponent, resolve: { data: DataResolver } },
  { path: '', redirectTo: '/home', pathMatch: 'full' }
];

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule]
})
export class AppRoutingModule { }
"},{"order":24,"type":"paragraph","text":"Explanation: In the `AppRoutingModule`, the `resolve` property is added to the 'details/:id' route, specifying `DataResolver` and assigning the resolved data to the key 'data'. This makes the resolved data available to the `DetailsComponent` through `route.snapshot.data['data']`."},{"order":25,"type":"paragraph","text":"By using `CanActivate`, `CanDeactivate`, and `Resolve` guards, you can effectively control navigation in your Angular application, ensuring that routes are accessed securely and that components have the necessary data before rendering."}]
